00102 inline uint32_t QuantRDOQ::xGetCodedLevel( double&            rd64CodedCost,
00103                                        double&            rd64CodedCost0,
00104                                        double&            rd64CodedCostSig,
00105                                        Intermediate_Int   lLevelDouble,
00106                                        uint32_t               uiMaxAbsLevel,
00107                                        const BinFracBits* fracBitsSig,
00108                                        const BinFracBits& fracBitsPar,
00109                                        const BinFracBits& fracBitsGt1,
00110                                        const BinFracBits& fracBitsGt2,
00111                                        const int          remRegBins,
00112                                        unsigned           goRiceZero,
00113                                        uint16_t             ui16AbsGoRice,
00114                                        int                iQBits,
00115                                        double             errorScale,
00116                                        bool               bLast,
00117                                        bool               useLimitedPrefixLength,
00118                                        const int          maxLog2TrDynamicRange
00119                                      ) const
00120 {
00121   double dCurrCostSig   = 0;
00122   uint32_t   uiBestAbsLevel = 0;
00123 
00124   if( !bLast && uiMaxAbsLevel < 3 )
00125   {
00126     rd64CodedCostSig    = xGetRateSigCoef( *fracBitsSig, 0 );
00127     rd64CodedCost       = rd64CodedCost0 + rd64CodedCostSig;
00128     if( uiMaxAbsLevel == 0 )
00129     {
00130       return uiBestAbsLevel;
00131     }
00132   }
00133   else
00134   {
00135     rd64CodedCost       = MAX_DOUBLE;
00136   }
00137 
00138   if( !bLast )
00139   {
00140     dCurrCostSig        = xGetRateSigCoef( *fracBitsSig, 1 );
00141   }
00142 
00143   uint32_t uiMinAbsLevel    = ( uiMaxAbsLevel > 1 ? uiMaxAbsLevel - 1 : 1 );
00144   for( int uiAbsLevel  = uiMaxAbsLevel; uiAbsLevel >= uiMinAbsLevel ; uiAbsLevel-- )
00145   {
00146     double dErr         = double( lLevelDouble  - ( Intermediate_Int(uiAbsLevel) << iQBits ) );
00147 
00148     double dCurrCost    = dErr * dErr * errorScale + xGetICost( xGetICRate( uiAbsLevel, fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, ui16AbsGoRice, true, maxLog2TrDynamicRange ) );
00149     dCurrCost          += dCurrCostSig;
00150 
00151     if( dCurrCost < rd64CodedCost )
00152     {
00153       uiBestAbsLevel    = uiAbsLevel;
00154       rd64CodedCost     = dCurrCost;
00155       rd64CodedCostSig  = dCurrCostSig;
00156     }
00157   }
00158 
00159   return uiBestAbsLevel;
00160 }
