00173 inline int QuantRDOQ::xGetICRate( const uint32_t         uiAbsLevel,
00174                                   const BinFracBits& fracBitsPar,
00175                                   const BinFracBits& fracBitsGt1,
00176                                   const BinFracBits& fracBitsGt2,
00177                                   const int          remRegBins,
00178                                   unsigned           goRiceZero,
00179                                   const uint16_t       ui16AbsGoRice,
00180                                   const bool         useLimitedPrefixLength,
00181                                   const int          maxLog2TrDynamicRange  ) const
00182 {
00183   if( remRegBins < 4 )
00184   {
00185     int       iRate   = int( xGetIEPRate() ); // cost of sign bit
00186     uint32_t  symbol  = ( uiAbsLevel == 0 ? goRiceZero : uiAbsLevel <= goRiceZero ? uiAbsLevel-1 : uiAbsLevel );
00187     uint32_t  length;
00188     const int threshold = COEF_REMAIN_BIN_REDUCTION;
00189     if( symbol < ( threshold << ui16AbsGoRice ) )
00190     {
00191       length = symbol >> ui16AbsGoRice;
00192       iRate += ( length + 1 + ui16AbsGoRice ) << SCALE_BITS;
00193     }
00194     else if( useLimitedPrefixLength )
00195     {
00196       const uint32_t maximumPrefixLength = ( 32 - ( COEF_REMAIN_BIN_REDUCTION + maxLog2TrDynamicRange ) );
00197 
00198       uint32_t prefixLength = 0;
00199       uint32_t suffix = ( symbol >> ui16AbsGoRice ) - COEF_REMAIN_BIN_REDUCTION;
00200 
00201       while( ( prefixLength < maximumPrefixLength ) && ( suffix > ( ( 2 << prefixLength ) - 2 ) ) )
00202       {
00203         prefixLength++;
00204       }
00205 
00206       const uint32_t suffixLength = ( prefixLength == maximumPrefixLength ) ? ( maxLog2TrDynamicRange - ui16AbsGoRice ) : ( prefixLength + 1/*separator*/ );
00207 
00208       iRate += ( COEF_REMAIN_BIN_REDUCTION + prefixLength + suffixLength + ui16AbsGoRice ) << SCALE_BITS;
00209     }
00210     else
00211     {
00212       length = ui16AbsGoRice;
00213       symbol = symbol - ( threshold << ui16AbsGoRice );
00214       while( symbol >= ( 1 << length ) )
00215       {
00216         symbol -= ( 1 << ( length++ ) );
00217       }
00218       iRate += ( threshold + length + 1 - ui16AbsGoRice + length ) << SCALE_BITS;
00219     }
00220     return iRate;
00221   }
00222 
00223   int iRate = int( xGetIEPRate() ); // cost of sign bit
00224   const uint32_t cthres = 4;
00225   if( uiAbsLevel >= cthres )
00226   {
00227     uint32_t symbol = ( uiAbsLevel - cthres ) >> 1;
00228     uint32_t length;
00229     const int threshold = COEF_REMAIN_BIN_REDUCTION;
00230     if( symbol < ( threshold << ui16AbsGoRice ) )
00231     {
00232       length = symbol >> ui16AbsGoRice;
00233       iRate += ( length + 1 + ui16AbsGoRice ) << SCALE_BITS;
00234     }
00235     else if( useLimitedPrefixLength )
00236     {
00237       const uint32_t maximumPrefixLength = ( 32 - ( COEF_REMAIN_BIN_REDUCTION + maxLog2TrDynamicRange ) );
00238 
00239       uint32_t prefixLength = 0;
00240       uint32_t suffix = ( symbol >> ui16AbsGoRice ) - COEF_REMAIN_BIN_REDUCTION;
00241 
00242       while( ( prefixLength < maximumPrefixLength ) && ( suffix > ( ( 2 << prefixLength ) - 2 ) ) )
00243       {
00244         prefixLength++;
00245       }
00246 
00247       const uint32_t suffixLength = ( prefixLength == maximumPrefixLength ) ? ( maxLog2TrDynamicRange - ui16AbsGoRice ) : ( prefixLength + 1/*separator*/ );
00248 
00249       iRate += ( COEF_REMAIN_BIN_REDUCTION + prefixLength + suffixLength + ui16AbsGoRice ) << SCALE_BITS;
00250     }
00251     else
00252     {
00253       length = ui16AbsGoRice;
00254       symbol = symbol - ( threshold << ui16AbsGoRice );
00255       while( symbol >= ( 1 << length ) )
00256       {
00257         symbol -= ( 1 << ( length++ ) );
00258       }
00259       iRate += ( threshold + length + 1 - ui16AbsGoRice + length ) << SCALE_BITS;
00260     }
00261 
00262     iRate += fracBitsGt1.intBits[1];
00263     iRate += fracBitsPar.intBits[( uiAbsLevel - 2 ) & 1];
00264     iRate += fracBitsGt2.intBits[1];
00265   }
00266   else if( uiAbsLevel == 1 )
00267   {
00268     iRate += fracBitsGt1.intBits[0];
00269   }
00270   else if( uiAbsLevel == 2 )
00271   {
00272     iRate += fracBitsGt1.intBits[1];
00273     iRate += fracBitsPar.intBits[0];
00274     iRate += fracBitsGt2.intBits[0];
00275   }
00276   else if( uiAbsLevel == 3 )
00277   {
00278     iRate += fracBitsGt1.intBits[1];
00279     iRate += fracBitsPar.intBits[1];
00280     iRate += fracBitsGt2.intBits[0];
00281   }
00282   else
00283   {
00284     iRate = 0;
00285   }
00286   return  iRate;
00287 }
