00303 inline double QuantRDOQ::xGetRateLast( const int* lastBitsX, const int* lastBitsY, unsigned PosX, unsigned PosY ) const
00304 {
00305   uint32_t    CtxX  = g_uiGroupIdx[PosX];
00306   uint32_t    CtxY  = g_uiGroupIdx[PosY];
00307   double  Cost  = lastBitsX[ CtxX ] + lastBitsY[ CtxY ];
00308   if( CtxX > 3 )
00309   {
00310     Cost += xGetIEPRate() * ((CtxX-2)>>1);
00311   }
00312   if( CtxY > 3 )
00313   {
00314     Cost += xGetIEPRate() * ((CtxY-2)>>1);
00315   }
00316   return xGetICost( Cost );
00317 }
