00350 void QuantRDOQ::setScalingList(ScalingList *scalingList, const int maxLog2TrDynamicRange[MAX_NUM_CHANNEL_TYPE], const BitDepths &bitDepths)
00351 {
00352   Quant::setScalingList( scalingList, maxLog2TrDynamicRange, bitDepths );
00353 
00354   const int minimumQp = 0;
00355   const int maximumQp = SCALING_LIST_REM_NUM;
00356 
00357   for(uint32_t size = 0; size < SCALING_LIST_SIZE_NUM; size++)
00358   {
00359     for(uint32_t list = 0; list < SCALING_LIST_NUM; list++)
00360     {
00361       for(int qp = minimumQp; qp < maximumQp; qp++)
00362       {
00363 //         xSetScalingListEnc(scalingList,list,size,qp);
00364 //         xSetScalingListDec(*scalingList,list,size,qp);
00365         xSetErrScaleCoeff(list,size, size,qp,maxLog2TrDynamicRange, bitDepths);
00366       }
00367     }
00368   }
00369 }
