00384 
00392 void QuantRDOQ::xSetErrScaleCoeff( uint32_t list, uint32_t sizeX, uint32_t sizeY, int qp, const int maxLog2TrDynamicRange[MAX_NUM_CHANNEL_TYPE], const BitDepths &bitDepths )
00393 {
00394   const int width = g_scalingListSizeX[sizeX];
00395   const int height = g_scalingListSizeX[sizeY];
00396   const ChannelType channelType = ( ( list == 0 ) || ( list == MAX_NUM_COMPONENT ) ) ? CHANNEL_TYPE_LUMA : CHANNEL_TYPE_CHROMA;
00397   const int channelBitDepth = bitDepths.recon[channelType];
00398   const int iTransformShift = getTransformShift( channelBitDepth, Size( g_scalingListSizeX[sizeX], g_scalingListSizeX[sizeY] ), maxLog2TrDynamicRange[channelType] );  // Represents scaling through forward transform
00399 
00400   uint32_t i, uiMaxNumCoeff = width * height;
00401   int *piQuantcoeff;
00402   double *pdErrScale;
00403   piQuantcoeff = getQuantCoeff( list, qp, sizeX, sizeY );
00404   pdErrScale   = xGetErrScaleCoeffSL( list, sizeX, sizeY, qp);
00405 
00406   double dErrScale = (double)( 1 << SCALE_BITS );                                // Compensate for scaling of bitcount in Lagrange cost function
00407 
00408   const bool needsSqrt2 = ((floorLog2(width) + floorLog2(height)) & 1) == 1;
00409   double dTransShift = (double)iTransformShift + ( needsSqrt2 ? -0.5 : 0.0 );
00410   dErrScale = dErrScale*pow( 2.0, ( -2.0*dTransShift ) );                     // Compensate for scaling through forward transform
00411 
00412   for( i = 0; i < uiMaxNumCoeff; i++ )
00413   {
00414     pdErrScale[i] = dErrScale / piQuantcoeff[i] / piQuantcoeff[i]
00415                     / (1 << (DISTORTION_PRECISION_ADJUSTMENT(bitDepths.recon[channelType]) << 1));
00416   }
00417 
00418   int QStep = g_quantScales[needsSqrt2][qp];
00419 
00420   xGetErrScaleCoeffNoScalingList(list, sizeX, sizeY, qp) =
00421     dErrScale / QStep / QStep / (1 << (DISTORTION_PRECISION_ADJUSTMENT(bitDepths.recon[channelType]) << 1));
00422 }
