00450 void QuantRDOQ::xInitScalingList( const QuantRDOQ* other )
00451 {
00452   m_isErrScaleListOwner = other == nullptr;
00453 
00454   size_t numElements = 0;
00455 
00456   for (uint32_t sizeIdX = 0; sizeIdX < SCALING_LIST_SIZE_NUM; sizeIdX++)
00457   {
00458     for (uint32_t sizeIdY = 0; sizeIdY < SCALING_LIST_SIZE_NUM; sizeIdY++)
00459     {
00460       for (uint32_t qp = 0; qp < SCALING_LIST_REM_NUM; qp++)
00461       {
00462         for (uint32_t listId = 0; listId < SCALING_LIST_NUM; listId++)
00463         {
00464           numElements += g_scalingListSizeX[sizeIdX] * g_scalingListSizeX[sizeIdY];
00465         }
00466       }
00467     }
00468   }
00469 
00470   if (m_isErrScaleListOwner)
00471   {
00472     m_errScale[0][0][0][0] = new double[numElements];
00473   }
00474 
00475   size_t offset = 0;
00476 
00477   for(uint32_t sizeIdX = 0; sizeIdX < SCALING_LIST_SIZE_NUM; sizeIdX++)
00478   {
00479     for(uint32_t sizeIdY = 0; sizeIdY < SCALING_LIST_SIZE_NUM; sizeIdY++)
00480     {
00481       for(uint32_t qp = 0; qp < SCALING_LIST_REM_NUM; qp++)
00482       {
00483         for(uint32_t listId = 0; listId < SCALING_LIST_NUM; listId++)
00484         {
00485           if( m_isErrScaleListOwner )
00486           {
00487             m_errScale[sizeIdX][sizeIdY][listId][qp] = m_errScale[0][0][0][0] + offset;
00488             offset += g_scalingListSizeX[sizeIdX] * g_scalingListSizeX[sizeIdY];
00489           }
00490           else
00491           {
00492             m_errScale[sizeIdX][sizeIdY][listId][qp] = other->m_errScale[sizeIdX][sizeIdY][listId][qp];
00493           }
00494         } // listID loop
00495       }
00496     }
00497   }
00498 }
00499 
00502 void QuantRDOQ::xDestroyScalingList()
00503 {
00504   if( !m_isErrScaleListOwner ) return;
00505 
00506   delete[] m_errScale[0][0][0][0];
00507 }
