00510 void QuantRDOQ::quant(TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pSrc, TCoeff &uiAbsSum, const QpParam &cQP, const Ctx& ctx)
00511 {
00512   const CompArea &rect      = tu.blocks[compID];
00513   const uint32_t uiWidth        = rect.width;
00514   const uint32_t uiHeight       = rect.height;
00515 
00516   const CCoeffBuf &piCoef   = pSrc;
00517         CoeffBuf   piQCoef  = tu.getCoeffs(compID);
00518 
00519   const bool useTransformSkip      = (tu.mtsIdx[compID] == MTS_SKIP);
00520 
00521   bool useRDOQ = useTransformSkip ? m_useRDOQTS : m_useRDOQ;
00522 
00523   if( !tu.cu->ispMode || !isLuma(compID) )
00524   {
00525     useRDOQ &= uiWidth > 2;
00526     useRDOQ &= uiHeight > 2;
00527   }
00528 
00529   if (tu.cs->slice->isLossless())
00530     useRDOQ = false;
00531 
00532   if (useRDOQ && (isLuma(compID) || RDOQ_CHROMA))
00533   {
00534 #if T0196_SELECTIVE_RDOQ
00535     if (!m_useSelectiveRDOQ || xNeedRDOQ(tu, compID, piCoef, cQP))
00536     {
00537 #endif
00538       if( useTransformSkip )
00539       {
00540         if( (tu.cu->bdpcmMode && isLuma(compID)) || (isChroma(compID) && tu.cu->bdpcmModeChroma ) )
00541         {
00542           forwardBDPCM(tu, compID, pSrc, uiAbsSum, cQP, ctx);
00543         }
00544         else
00545         {
00546           xRateDistOptQuantTS( tu, compID, pSrc, uiAbsSum, cQP, ctx );
00547         }
00548       }
00549       else
00550       {
00551         xRateDistOptQuant( tu, compID, pSrc, uiAbsSum, cQP, ctx );
00552       }
00553 #if T0196_SELECTIVE_RDOQ
00554     }
00555     else
00556     {
00557       piQCoef.fill(0);
00558       uiAbsSum = 0;
00559     }
00560 #endif
00561   }
00562   else
00563   {
00564     Quant::quant( tu, compID, pSrc, uiAbsSum, cQP, ctx );
00565   }
00566 }
