00569 
00570 void QuantRDOQ::xRateDistOptQuant(TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pSrc, TCoeff &uiAbsSum, const QpParam &cQP, const Ctx &ctx)
00571 {
00572   const FracBitsAccess& fracBits = ctx.getFracBitsAcess();
00573 
00574   const SPS &sps            = *tu.cs->sps;
00575   const CompArea &rect      = tu.blocks[compID];
00576   const uint32_t uiWidth        = rect.width;
00577   const uint32_t uiHeight       = rect.height;
00578   const ChannelType chType  = toChannelType(compID);
00579   const int channelBitDepth = sps.getBitDepth( chType );
00580 
00581   const bool extendedPrecision     = sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag();
00582   const int  maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange(chType);
00583 
00584   const bool useIntraSubPartitions = tu.cu->ispMode && isLuma(compID);
00585   /* for 422 chroma blocks, the effective scaling applied during transformation is not a power of 2, hence it cannot be
00586   * implemented as a bit-shift (the quantised result will be sqrt(2) * larger than required). Alternatively, adjust the
00587   * uiLog2TrSize applied in iTransformShift, such that the result is 1/sqrt(2) the required result (i.e. smaller)
00588   * Then a QP+3 (sqrt(2)) or QP-3 (1/sqrt(2)) method could be used to get the required result
00589   */
00590 
00591   // Represents scaling through forward transform
00592   int iTransformShift = getTransformShift(channelBitDepth, rect.size(), maxLog2TrDynamicRange);
00593 
00594   if (tu.mtsIdx[compID] == MTS_SKIP && extendedPrecision)
00595   {
00596     iTransformShift = std::max<int>(0, iTransformShift);
00597   }
00598 
00599   double     d64BlockUncodedCost               = 0;
00600   const uint32_t uiLog2BlockWidth                  = floorLog2(uiWidth);
00601   const uint32_t uiLog2BlockHeight                 = floorLog2(uiHeight);
00602   const uint32_t uiMaxNumCoeff                     = rect.area();
00603 
00604   CHECK(compID >= MAX_NUM_TBLOCKS, "Invalid component ID");
00605 
00606   int scalingListType = getScalingListType(tu.cu->predMode, compID);
00607 
00608   CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
00609 
00610   const TCoeff *plSrcCoeff = pSrc.buf;
00611         TCoeff *piDstCoeff = tu.getCoeffs(compID).buf;
00612 
00613   double *pdCostCoeff  = m_pdCostCoeff;
00614   double *pdCostSig    = m_pdCostSig;
00615   double *pdCostCoeff0 = m_pdCostCoeff0;
00616   int    *rateIncUp    = m_rateIncUp;
00617   int    *rateIncDown  = m_rateIncDown;
00618   int    *sigRateDelta = m_sigRateDelta;
00619   TCoeff *deltaU       = m_deltaU;
00620 
00621   memset(piDstCoeff, 0, sizeof(*piDstCoeff) * uiMaxNumCoeff);
00622   memset( m_pdCostCoeff,  0, sizeof( double ) *  uiMaxNumCoeff );
00623   memset( m_pdCostSig,    0, sizeof( double ) *  uiMaxNumCoeff );
00624   memset( m_rateIncUp,    0, sizeof( int    ) *  uiMaxNumCoeff );
00625   memset( m_rateIncDown,  0, sizeof( int    ) *  uiMaxNumCoeff );
00626   memset( m_sigRateDelta, 0, sizeof( int    ) *  uiMaxNumCoeff );
00627   memset( m_deltaU,       0, sizeof( TCoeff ) *  uiMaxNumCoeff );
00628 
00629 
00630   const bool needSqrtAdjustment= TU::needsBlockSizeTrafoScale( tu, compID );
00631   const bool   isTransformSkip = (tu.mtsIdx[compID] == MTS_SKIP);
00632   const double *const pdErrScale = xGetErrScaleCoeffSL(scalingListType, uiLog2BlockWidth, uiLog2BlockHeight, cQP.rem(isTransformSkip));
00633   const int    *const piQCoef    = getQuantCoeff(scalingListType, cQP.rem(isTransformSkip), uiLog2BlockWidth, uiLog2BlockHeight);
00634 
00635   const bool   disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
00636   const bool   isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
00637   const bool   disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
00638   const bool   enableScalingLists = getUseScalingList(uiWidth, uiHeight, isTransformSkip, isLfnstApplied, disableSMForLFNST, disableSMForACT);
00639   const int    defaultQuantisationCoefficient = g_quantScales[ needSqrtAdjustment ?1:0][cQP.rem(isTransformSkip)];
00640   const double defaultErrorScale              = xGetErrScaleCoeffNoScalingList(scalingListType, uiLog2BlockWidth, uiLog2BlockHeight, cQP.rem(isTransformSkip));
00641   const int iQBits = QUANT_SHIFT + cQP.per(isTransformSkip) + iTransformShift + (needSqrtAdjustment?-1:0);                   // Right shift of non-RDOQ quantizer;  level = (coeff*uiQ + offset)>>q_bits
00642 
00643 
00644   const TCoeff entropyCodingMinimum = -(1 << maxLog2TrDynamicRange);
00645   const TCoeff entropyCodingMaximum =  (1 << maxLog2TrDynamicRange) - 1;
00646   
00647   CoeffCodingContext cctx(tu, compID, tu.cs->slice->getSignDataHidingEnabledFlag());
00648   const int    iCGSizeM1      = (1 << cctx.log2CGSize()) - 1;
00649 
00650   int     iCGLastScanPos      = -1;
00651   double  d64BaseCost         = 0;
00652   int     iLastScanPos        = -1;
00653 
00654   int ctxBinSampleRatio = (compID == COMPONENT_Y) ? MAX_TU_LEVEL_CTX_CODED_BIN_CONSTRAINT_LUMA : MAX_TU_LEVEL_CTX_CODED_BIN_CONSTRAINT_CHROMA;
00655   int remRegBins = (uiWidth * uiHeight * ctxBinSampleRatio) >> 4;
00656   uint32_t  goRiceParam   = 0;
00657 
00658   double *pdCostCoeffGroupSig = m_pdCostCoeffGroupSig;
00659   memset( pdCostCoeffGroupSig, 0, ( uiMaxNumCoeff >> cctx.log2CGSize() ) * sizeof( double ) );
00660   int iScanPos;
00661   coeffGroupRDStats rdStats;
00662 
00663 #if ENABLE_TRACING
00664   DTRACE( g_trace_ctx, D_RDOQ, "%d: %3d, %3d, %dx%d, comp=%d\n", DTRACE_GET_COUNTER( g_trace_ctx, D_RDOQ ), rect.x, rect.y, rect.width, rect.height, compID );
00665 #endif
00666 
00667   const uint32_t lfnstIdx = tu.cu->lfnstIdx;
00668 
00669   const int iCGNum = lfnstIdx > 0 ? 1 : std::min<int>(JVET_C0024_ZERO_OUT_TH, uiWidth) * std::min<int>(JVET_C0024_ZERO_OUT_TH, uiHeight) >> cctx.log2CGSize();
00670 
00671   for (int subSetId = iCGNum - 1; subSetId >= 0; subSetId--)
00672   {
00673     cctx.initSubblock( subSetId );
00674 
00675     uint32_t maxNonZeroPosInCG = iCGSizeM1;
00676     if( lfnstIdx > 0 && ( ( uiWidth == 4 && uiHeight == 4 ) || ( uiWidth == 8 && uiHeight == 8 && cctx.cgPosX() == 0 && cctx.cgPosY() == 0 ) ) )
00677     {
00678       maxNonZeroPosInCG = 7;
00679     }
00680 
00681     memset( &rdStats, 0, sizeof (coeffGroupRDStats));
00682 
00683     for( int iScanPosinCG = iCGSizeM1; iScanPosinCG > maxNonZeroPosInCG; iScanPosinCG-- )
00684     {
00685       iScanPos = cctx.minSubPos() + iScanPosinCG;
00686       uint32_t    blkPos = cctx.blockPos( iScanPos );
00687       piDstCoeff[ blkPos ] = 0;
00688     }
00689     for( int iScanPosinCG = maxNonZeroPosInCG; iScanPosinCG >= 0; iScanPosinCG-- )
00690     {
00691       iScanPos = cctx.minSubPos() + iScanPosinCG;
00692       //===== quantization =====
00693       uint32_t    uiBlkPos          = cctx.blockPos(iScanPos);
00694 
00695       // set coeff
00696       const int    quantisationCoefficient = (enableScalingLists) ? piQCoef   [uiBlkPos]               : defaultQuantisationCoefficient;
00697       const double errorScale              = (enableScalingLists) ? pdErrScale[uiBlkPos]               : defaultErrorScale;
00698       const int64_t  tmpLevel                = int64_t(abs(plSrcCoeff[ uiBlkPos ])) * quantisationCoefficient;
00699 
00700       const Intermediate_Int lLevelDouble  = (Intermediate_Int)std::min<int64_t>(tmpLevel, std::numeric_limits<Intermediate_Int>::max() - (Intermediate_Int(1) << (iQBits - 1)));
00701 
00702       uint32_t uiMaxAbsLevel        = std::min<uint32_t>(uint32_t(entropyCodingMaximum), uint32_t((lLevelDouble + (Intermediate_Int(1) << (iQBits - 1))) >> iQBits));
00703 
00704       const double dErr         = double( lLevelDouble );
00705       pdCostCoeff0[ iScanPos ]  = dErr * dErr * errorScale;
00706       d64BlockUncodedCost      += pdCostCoeff0[ iScanPos ];
00707       piDstCoeff[ uiBlkPos ]    = uiMaxAbsLevel;
00708 
00709       if ( uiMaxAbsLevel > 0 && iLastScanPos < 0 )
00710       {
00711         iLastScanPos            = iScanPos;
00712         iCGLastScanPos          = cctx.subSetId();
00713       }
00714 
00715       if ( iLastScanPos >= 0 )
00716       {
00717 
00718 #if ENABLE_TRACING
00719         uint32_t uiCGPosY = cctx.cgPosX();
00720         uint32_t uiCGPosX = cctx.cgPosY();
00721         uint32_t uiPosY = cctx.posY( iScanPos );
00722         uint32_t uiPosX = cctx.posX( iScanPos );
00723         DTRACE( g_trace_ctx, D_RDOQ, "%d [%d][%d][%2d:%2d][%2d:%2d]", DTRACE_GET_COUNTER( g_trace_ctx, D_RDOQ ), iScanPos, uiBlkPos, uiCGPosX, uiCGPosY, uiPosX, uiPosY );
00724 #endif
00725         //===== coefficient level estimation =====
00726         unsigned ctxIdSig = 0;
00727         if( iScanPos != iLastScanPos )
00728         {
00729           ctxIdSig = cctx.sigCtxIdAbs( iScanPos, piDstCoeff, 0 );
00730         }
00731         uint32_t    uiLevel;
00732         uint8_t ctxOffset     = cctx.ctxOffsetAbs     ();
00733         uint32_t    uiParCtx      = cctx.parityCtxIdAbs   ( ctxOffset );
00734         uint32_t    uiGt1Ctx      = cctx.greater1CtxIdAbs ( ctxOffset );
00735         uint32_t    uiGt2Ctx      = cctx.greater2CtxIdAbs ( ctxOffset );
00736         uint32_t    goRiceZero    = 0;
00737         if( remRegBins < 4 )
00738         {
00739           unsigned  sumAbs = cctx.templateAbsSum( iScanPos, piDstCoeff, 0 );
00740           goRiceParam             = g_auiGoRiceParsCoeff   [ sumAbs ];
00741           goRiceZero              = g_auiGoRicePosCoeff0(0, goRiceParam);
00742         }
00743 
00744         const BinFracBits fracBitsPar = fracBits.getFracBitsArray( uiParCtx );
00745         const BinFracBits fracBitsGt1 = fracBits.getFracBitsArray( uiGt1Ctx );
00746         const BinFracBits fracBitsGt2 = fracBits.getFracBitsArray( uiGt2Ctx );
00747 
00748         if( iScanPos == iLastScanPos )
00749         {
00750           uiLevel = xGetCodedLevel( pdCostCoeff[ iScanPos ], pdCostCoeff0[ iScanPos ], pdCostSig[ iScanPos ],
00751                                     lLevelDouble, uiMaxAbsLevel, nullptr, fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, iQBits, errorScale, 1, extendedPrecision, maxLog2TrDynamicRange );
00752         }
00753         else
00754         {
00755           DTRACE_COND( ( uiMaxAbsLevel != 0 ), g_trace_ctx, D_RDOQ_MORE, " uiCtxSig=%d", ctxIdSig );
00756 
00757           const BinFracBits fracBitsSig = fracBits.getFracBitsArray( ctxIdSig );
00758           uiLevel = xGetCodedLevel( pdCostCoeff[ iScanPos ], pdCostCoeff0[ iScanPos ], pdCostSig[ iScanPos ],
00759                                     lLevelDouble, uiMaxAbsLevel, &fracBitsSig, fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, iQBits, errorScale, 0, extendedPrecision, maxLog2TrDynamicRange );
00760           sigRateDelta[ uiBlkPos ] = ( remRegBins < 4 ? 0 : fracBitsSig.intBits[1] - fracBitsSig.intBits[0] );
00761         }
00762 
00763         DTRACE( g_trace_ctx, D_RDOQ, " Lev=%d \n", uiLevel );
00764         DTRACE_COND( ( uiMaxAbsLevel != 0 ), g_trace_ctx, D_RDOQ, " CostC0=%d\n", (int64_t)( pdCostCoeff0[iScanPos] ) );
00765         DTRACE_COND( ( uiMaxAbsLevel != 0 ), g_trace_ctx, D_RDOQ, " CostC =%d\n", (int64_t)( pdCostCoeff[iScanPos] ) );
00766 
00767         deltaU[ uiBlkPos ]        = TCoeff((lLevelDouble - (Intermediate_Int(uiLevel) << iQBits)) >> (iQBits-8));
00768 
00769         if( uiLevel > 0 )
00770         {
00771           int rateNow              = xGetICRate( uiLevel,   fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, extendedPrecision, maxLog2TrDynamicRange );
00772           rateIncUp   [ uiBlkPos ] = xGetICRate( uiLevel+1, fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, extendedPrecision, maxLog2TrDynamicRange ) - rateNow;
00773           rateIncDown [ uiBlkPos ] = xGetICRate( uiLevel-1, fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, extendedPrecision, maxLog2TrDynamicRange ) - rateNow;
00774         }
00775         else // uiLevel == 0
00776         {
00777           if( remRegBins < 4 )
00778           {
00779             int rateNow            = xGetICRate( uiLevel,   fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, extendedPrecision, maxLog2TrDynamicRange );
00780             rateIncUp [ uiBlkPos ] = xGetICRate( uiLevel+1, fracBitsPar, fracBitsGt1, fracBitsGt2, remRegBins, goRiceZero, goRiceParam, extendedPrecision, maxLog2TrDynamicRange ) - rateNow;
00781           }
00782           else
00783           {
00784             rateIncUp [ uiBlkPos ] = fracBitsGt1.intBits[ 0 ];
00785           }
00786         }
00787         piDstCoeff[ uiBlkPos ] = uiLevel;
00788         d64BaseCost           += pdCostCoeff [ iScanPos ];
00789 
00790         if( ( (iScanPos & iCGSizeM1) == 0 ) && ( iScanPos > 0 ) )
00791         {
00792           goRiceParam   = 0;
00793         }
00794         else if( remRegBins >= 4 )
00795         {
00796           int  sumAll = cctx.templateAbsSum(iScanPos, piDstCoeff, 4);
00797           goRiceParam = g_auiGoRiceParsCoeff[sumAll];
00798           remRegBins -= (uiLevel < 2 ? uiLevel : 3) + (iScanPos != iLastScanPos);
00799         }
00800       }
00801       else
00802       {
00803         d64BaseCost    += pdCostCoeff0[ iScanPos ];
00804       }
00805       rdStats.d64SigCost += pdCostSig[ iScanPos ];
00806       if (iScanPosinCG == 0 )
00807       {
00808         rdStats.d64SigCost_0 = pdCostSig[ iScanPos ];
00809       }
00810       if (piDstCoeff[ uiBlkPos ] )
00811       {
00812         cctx.setSigGroup();
00813         rdStats.d64CodedLevelandDist += pdCostCoeff[ iScanPos ] - pdCostSig[ iScanPos ];
00814         rdStats.d64UncodedDist += pdCostCoeff0[ iScanPos ];
00815         if ( iScanPosinCG != 0 )
00816         {
00817           rdStats.iNNZbeforePos0++;
00818         }
00819       }
00820     } //end for (iScanPosinCG)
00821 
00822     if (iCGLastScanPos >= 0)
00823     {
00824       if( cctx.subSetId() )
00825       {
00826         if( !cctx.isSigGroup() )
00827         {
00828           const BinFracBits fracBitsSigGroup = fracBits.getFracBitsArray( cctx.sigGroupCtxId() );
00829           d64BaseCost += xGetRateSigCoeffGroup(fracBitsSigGroup, 0) - rdStats.d64SigCost;
00830           pdCostCoeffGroupSig[ cctx.subSetId() ] = xGetRateSigCoeffGroup(fracBitsSigGroup, 0);
00831         }
00832         else
00833         {
00834           if (cctx.subSetId() < iCGLastScanPos) //skip the last coefficient group, which will be handled together with last position below.
00835           {
00836             if ( rdStats.iNNZbeforePos0 == 0 )
00837             {
00838               d64BaseCost -= rdStats.d64SigCost_0;
00839               rdStats.d64SigCost -= rdStats.d64SigCost_0;
00840             }
00841             // rd-cost if SigCoeffGroupFlag = 0, initialization
00842             double d64CostZeroCG = d64BaseCost;
00843 
00844             const BinFracBits fracBitsSigGroup = fracBits.getFracBitsArray( cctx.sigGroupCtxId() );
00845 
00846             if (cctx.subSetId() < iCGLastScanPos)
00847             {
00848               d64BaseCost  += xGetRateSigCoeffGroup(fracBitsSigGroup,1);
00849               d64CostZeroCG += xGetRateSigCoeffGroup(fracBitsSigGroup,0);
00850               pdCostCoeffGroupSig[ cctx.subSetId() ] = xGetRateSigCoeffGroup(fracBitsSigGroup,1);
00851             }
00852 
00853             // try to convert the current coeff group from non-zero to all-zero
00854             d64CostZeroCG += rdStats.d64UncodedDist;  // distortion for resetting non-zero levels to zero levels
00855             d64CostZeroCG -= rdStats.d64CodedLevelandDist;   // distortion and level cost for keeping all non-zero levels
00856             d64CostZeroCG -= rdStats.d64SigCost;     // sig cost for all coeffs, including zero levels and non-zerl levels
00857 
00858                                                      // if we can save cost, change this block to all-zero block
00859             if ( d64CostZeroCG < d64BaseCost )
00860             {
00861               cctx.resetSigGroup();
00862               d64BaseCost = d64CostZeroCG;
00863               if (cctx.subSetId() < iCGLastScanPos)
00864               {
00865                 pdCostCoeffGroupSig[ cctx.subSetId() ] = xGetRateSigCoeffGroup(fracBitsSigGroup,0);
00866               }
00867               // reset coeffs to 0 in this block
00868               for( int iScanPosinCG = maxNonZeroPosInCG; iScanPosinCG >= 0; iScanPosinCG-- )
00869               {
00870                 iScanPos      = cctx.minSubPos() + iScanPosinCG;
00871                 uint32_t uiBlkPos = cctx.blockPos( iScanPos );
00872 
00873                 if (piDstCoeff[ uiBlkPos ])
00874                 {
00875                   piDstCoeff [ uiBlkPos ] = 0;
00876                   pdCostCoeff[ iScanPos ] = pdCostCoeff0[ iScanPos ];
00877                   pdCostSig  [ iScanPos ] = 0;
00878                 }
00879               }
00880             } // end if ( d64CostAllZeros < d64BaseCost )
00881           }
00882         } // end if if (uiSigCoeffGroupFlag[ uiCGBlkPos ] == 0)
00883       }
00884       else
00885       {
00886         cctx.setSigGroup();
00887       }
00888     }
00889   } //end for (cctx.subSetId)
00890 
00891 
00892   //===== estimate last position =====
00893   if ( iLastScanPos < 0 )
00894   {
00895     return;
00896   }
00897 
00898   double  d64BestCost         = 0;
00899   int     iBestLastIdxP1      = 0;
00900 
00901 
00902   if( !CU::isIntra( *tu.cu ) && isLuma( compID ) && tu.depth == 0 )
00903   {
00904     const BinFracBits fracBitsQtRootCbf = fracBits.getFracBitsArray( Ctx::QtRootCbf() );
00905     d64BestCost  = d64BlockUncodedCost + xGetICost( fracBitsQtRootCbf.intBits[ 0 ] );
00906     d64BaseCost += xGetICost( fracBitsQtRootCbf.intBits[ 1 ] );
00907   }
00908   else
00909   {
00910     bool previousCbf       = tu.cbf[COMPONENT_Cb];
00911     bool lastCbfIsInferred = false;
00912     if( useIntraSubPartitions )
00913     {
00914       bool rootCbfSoFar       = false;
00915       bool isLastSubPartition = CU::isISPLast(*tu.cu, tu.Y(), compID);
00916       uint32_t nTus = tu.cu->ispMode == HOR_INTRA_SUBPARTITIONS ? tu.cu->lheight() >> floorLog2(tu.lheight()) : tu.cu->lwidth() >> floorLog2(tu.lwidth());
00917       if( isLastSubPartition )
00918       {
00919         TransformUnit* tuPointer = tu.cu->firstTU;
00920         for( int tuIdx = 0; tuIdx < nTus - 1; tuIdx++ )
00921         {
00922           rootCbfSoFar |= TU::getCbfAtDepth(*tuPointer, COMPONENT_Y, tu.depth);
00923           tuPointer     = tuPointer->next;
00924         }
00925         if( !rootCbfSoFar )
00926         {
00927           lastCbfIsInferred = true;
00928         }
00929       }
00930       if( !lastCbfIsInferred )
00931       {
00932         previousCbf = TU::getPrevTuCbfAtDepth(tu, compID, tu.depth);
00933       }
00934     }
00935     BinFracBits fracBitsQtCbf = fracBits.getFracBitsArray( Ctx::QtCbf[compID]( DeriveCtx::CtxQtCbf( rect.compID, previousCbf, useIntraSubPartitions ) ) );
00936 
00937     if( !lastCbfIsInferred )
00938     {
00939       d64BestCost  = d64BlockUncodedCost + xGetICost(fracBitsQtCbf.intBits[0]);
00940       d64BaseCost += xGetICost(fracBitsQtCbf.intBits[1]);
00941     }
00942     else
00943     {
00944       d64BestCost  = d64BlockUncodedCost;
00945     }
00946   }
00947 
00948   int lastBitsX[LAST_SIGNIFICANT_GROUPS] = { 0 };
00949   int lastBitsY[LAST_SIGNIFICANT_GROUPS] = { 0 };
00950   {
00951     int dim1 = std::min<int>(JVET_C0024_ZERO_OUT_TH, uiWidth);
00952     int dim2 = std::min<int>(JVET_C0024_ZERO_OUT_TH, uiHeight);
00953     int bitsX = 0;
00954     int bitsY = 0;
00955     int ctxId;
00956     //X-coordinate
00957     for ( ctxId = 0; ctxId < g_uiGroupIdx[dim1-1]; ctxId++)
00958     {
00959       const BinFracBits fB = fracBits.getFracBitsArray( cctx.lastXCtxId(ctxId) );
00960       lastBitsX[ ctxId ]   = bitsX + fB.intBits[ 0 ];
00961       bitsX               +=         fB.intBits[ 1 ];
00962     }
00963     lastBitsX[ctxId] = bitsX;
00964     //Y-coordinate
00965     for ( ctxId = 0; ctxId < g_uiGroupIdx[dim2-1]; ctxId++)
00966     {
00967       const BinFracBits fB = fracBits.getFracBitsArray( cctx.lastYCtxId(ctxId) );
00968       lastBitsY[ ctxId ]   = bitsY + fB.intBits[ 0 ];
00969       bitsY               +=         fB.intBits[ 1 ];
00970     }
00971     lastBitsY[ctxId] = bitsY;
00972   }
00973 
00974 
00975   bool bFoundLast = false;
00976   for (int iCGScanPos = iCGLastScanPos; iCGScanPos >= 0; iCGScanPos--)
00977   {
00978     d64BaseCost -= pdCostCoeffGroupSig [ iCGScanPos ];
00979     if (cctx.isSigGroup( iCGScanPos ) )
00980     {
00981       uint32_t maxNonZeroPosInCG = iCGSizeM1;
00982       if( lfnstIdx > 0 && ( ( uiWidth == 4 && uiHeight == 4 ) || ( uiWidth == 8 && uiHeight == 8 && cctx.cgPosX() == 0 && cctx.cgPosY() == 0 ) ) )
00983       {
00984         maxNonZeroPosInCG = 7;
00985       }
00986       for( int iScanPosinCG = maxNonZeroPosInCG; iScanPosinCG >= 0; iScanPosinCG-- )
00987       {
00988         iScanPos = iCGScanPos * (iCGSizeM1 + 1) + iScanPosinCG;
00989 
00990         if (iScanPos > iLastScanPos)
00991         {
00992           continue;
00993         }
00994         uint32_t   uiBlkPos     = cctx.blockPos( iScanPos );
00995 
00996         if( piDstCoeff[ uiBlkPos ] )
00997         {
00998           uint32_t   uiPosY = uiBlkPos >> uiLog2BlockWidth;
00999           uint32_t   uiPosX = uiBlkPos - ( uiPosY << uiLog2BlockWidth );
01000           double d64CostLast  = xGetRateLast( lastBitsX, lastBitsY, uiPosX, uiPosY );
01001 
01002           double totalCost = d64BaseCost + d64CostLast - pdCostSig[ iScanPos ];
01003 
01004           if( totalCost < d64BestCost )
01005           {
01006             iBestLastIdxP1  = iScanPos + 1;
01007             d64BestCost     = totalCost;
01008           }
01009           if( piDstCoeff[ uiBlkPos ] > 1 )
01010           {
01011             bFoundLast = true;
01012             break;
01013           }
01014           d64BaseCost      -= pdCostCoeff[ iScanPos ];
01015           d64BaseCost      += pdCostCoeff0[ iScanPos ];
01016         }
01017         else
01018         {
01019           d64BaseCost      -= pdCostSig[ iScanPos ];
01020         }
01021       } //end for
01022       if (bFoundLast)
01023       {
01024         break;
01025       }
01026     } // end if (uiSigCoeffGroupFlag[ uiCGBlkPos ])
01027     DTRACE( g_trace_ctx, D_RDOQ_COST, "%d: %3d, %3d, %dx%d, comp=%d\n", DTRACE_GET_COUNTER( g_trace_ctx, D_RDOQ_COST ), rect.x, rect.y, rect.width, rect.height, compID );
01028     DTRACE( g_trace_ctx, D_RDOQ_COST, "Uncoded=%d\n", (int64_t)( d64BlockUncodedCost ) );
01029     DTRACE( g_trace_ctx, D_RDOQ_COST, "Coded  =%d\n", (int64_t)( d64BaseCost ) );
01030 
01031   } // end for
01032 
01033 
01034   for ( int scanPos = 0; scanPos < iBestLastIdxP1; scanPos++ )
01035   {
01036     int blkPos = cctx.blockPos( scanPos );
01037     TCoeff level = piDstCoeff[ blkPos ];
01038     uiAbsSum += level;
01039     piDstCoeff[ blkPos ] = ( plSrcCoeff[ blkPos ] < 0 ) ? -level : level;
01040   }
01041 
01042   //===== clean uncoded coefficients =====
01043   for ( int scanPos = iBestLastIdxP1; scanPos <= iLastScanPos; scanPos++ )
01044   {
01045     piDstCoeff[ cctx.blockPos( scanPos ) ] = 0;
01046   }
01047 
01048   if( cctx.signHiding() && uiAbsSum>=2)
01049   {
01050     const double inverseQuantScale = double(g_invQuantScales[0][cQP.rem(isTransformSkip)]);
01051     int64_t rdFactor = (int64_t)(inverseQuantScale * inverseQuantScale * (1 << (2 * cQP.per(isTransformSkip))) / m_dLambda / 16
01052                                   / (1 << (2 * DISTORTION_PRECISION_ADJUSTMENT(channelBitDepth)))
01053                              + 0.5);
01054 
01055     int lastCG = -1;
01056     int absSum = 0 ;
01057     int n ;
01058     for (int subSet = iCGNum - 1; subSet >= 0; subSet--)
01059     {
01060       int  subPos         = subSet << cctx.log2CGSize();
01061       int  firstNZPosInCG = iCGSizeM1 + 1, lastNZPosInCG = -1;
01062       absSum = 0 ;
01063 
01064       for( n = iCGSizeM1; n >= 0; --n )
01065       {
01066         if( piDstCoeff[ cctx.blockPos( n + subPos )] )
01067         {
01068           lastNZPosInCG = n;
01069           break;
01070         }
01071       }
01072 
01073       for( n = 0; n <= iCGSizeM1; n++ )
01074       {
01075         if( piDstCoeff[ cctx.blockPos( n + subPos )] )
01076         {
01077           firstNZPosInCG = n;
01078           break;
01079         }
01080       }
01081 
01082       for( n = firstNZPosInCG; n <= lastNZPosInCG; n++ )
01083       {
01084         absSum += int(piDstCoeff[ cctx.blockPos( n + subPos )]);
01085       }
01086 
01087       if(lastNZPosInCG>=0 && lastCG==-1)
01088       {
01089         lastCG = 1;
01090       }
01091 
01092       if( lastNZPosInCG-firstNZPosInCG>=SBH_THRESHOLD )
01093       {
01094         uint32_t signbit = (piDstCoeff[cctx.blockPos(subPos+firstNZPosInCG)]>0?0:1);
01095         if( signbit!=(absSum&0x1) )  // hide but need tune
01096         {
01097           // calculate the cost
01098           int64_t minCostInc = std::numeric_limits<int64_t>::max(), curCost = std::numeric_limits<int64_t>::max();
01099           int minPos = -1, finalChange = 0, curChange = 0;
01100 
01101           for( n = (lastCG == 1 ? lastNZPosInCG : iCGSizeM1); n >= 0; --n )
01102           {
01103             uint32_t uiBlkPos   = cctx.blockPos( n + subPos );
01104             if(piDstCoeff[ uiBlkPos ] != 0 )
01105             {
01106               int64_t costUp   = rdFactor * ( - deltaU[uiBlkPos] ) + rateIncUp[uiBlkPos];
01107               int64_t costDown = rdFactor * (   deltaU[uiBlkPos] ) + rateIncDown[uiBlkPos]
01108                 -   ((abs(piDstCoeff[uiBlkPos]) == 1) ? sigRateDelta[uiBlkPos] : 0);
01109 
01110               if(lastCG==1 && lastNZPosInCG==n && abs(piDstCoeff[uiBlkPos])==1)
01111               {
01112                 costDown -= (4<<SCALE_BITS);
01113               }
01114 
01115               if(costUp<costDown)
01116               {
01117                 curCost = costUp;
01118                 curChange =  1;
01119               }
01120               else
01121               {
01122                 curChange = -1;
01123                 if(n==firstNZPosInCG && abs(piDstCoeff[uiBlkPos])==1)
01124                 {
01125                   curCost = std::numeric_limits<int64_t>::max();
01126                 }
01127                 else
01128                 {
01129                   curCost = costDown;
01130                 }
01131               }
01132             }
01133             else
01134             {
01135               curCost = rdFactor * ( - (abs(deltaU[uiBlkPos])) ) + (1<<SCALE_BITS) + rateIncUp[uiBlkPos] + sigRateDelta[uiBlkPos] ;
01136               curChange = 1 ;
01137 
01138               if(n<firstNZPosInCG)
01139               {
01140                 uint32_t thissignbit = (plSrcCoeff[uiBlkPos]>=0?0:1);
01141                 if(thissignbit != signbit )
01142                 {
01143                   curCost = std::numeric_limits<int64_t>::max();
01144                 }
01145               }
01146             }
01147 
01148             if( curCost<minCostInc)
01149             {
01150               minCostInc = curCost;
01151               finalChange = curChange;
01152               minPos = uiBlkPos;
01153             }
01154           }
01155 
01156           if(piDstCoeff[minPos] == entropyCodingMaximum || piDstCoeff[minPos] == entropyCodingMinimum)
01157           {
01158             finalChange = -1;
01159           }
01160 
01161           if(plSrcCoeff[minPos]>=0)
01162           {
01163             piDstCoeff[minPos] += finalChange ;
01164           }
01165           else
01166           {
01167             piDstCoeff[minPos] -= finalChange ;
01168           }
01169         }
01170       }
01171 
01172       if(lastCG==1)
01173       {
01174         lastCG=0 ;
01175       }
01176     }
01177   }
01178 }
01179 
01180 void QuantRDOQ::xRateDistOptQuantTS( TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &coeffs, TCoeff &absSum, const QpParam &qp, const Ctx &ctx )
01181 {
01182   const FracBitsAccess& fracBits = ctx.getFracBitsAcess();
01183 
01184   const SPS &sps            = *tu.cs->sps;
01185   const CompArea &rect      = tu.blocks[compID];
01186   const uint32_t width      = rect.width;
01187   const uint32_t height     = rect.height;
01188   const ChannelType chType  = toChannelType(compID);
01189   const int channelBitDepth = sps.getBitDepth( chType );
01190 
01191   const bool extendedPrecision     = sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag();
01192   const int  maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange(chType);
01193 
01194   int transformShift = getTransformShift( channelBitDepth, rect.size(), maxLog2TrDynamicRange );
01195 
01196   if( extendedPrecision )
01197   {
01198     transformShift = std::max<int>( 0, transformShift );
01199   }
01200 
01201         double   blockUncodedCost                   = 0;
01202   const uint32_t maxNumCoeff                        = rect.area();
01203 
01204   CHECK( compID >= MAX_NUM_TBLOCKS, "Invalid component ID" );
01205 
01206   int scalingListType = getScalingListType( tu.cu->predMode, compID );
01207   CHECK( scalingListType >= SCALING_LIST_NUM, "Invalid scaling list" );
01208 
01209   const TCoeff *srcCoeff = coeffs.buf;
01210         TCoeff *dstCoeff = tu.getCoeffs( compID ).buf;
01211 
01212   double *costCoeff  = m_pdCostCoeff;
01213   double *costSig    = m_pdCostSig;
01214   double *costCoeff0 = m_pdCostCoeff0;
01215 
01216   memset( m_pdCostCoeff,  0, sizeof( double ) *  maxNumCoeff );
01217   memset( m_pdCostSig,    0, sizeof( double ) *  maxNumCoeff );
01218 
01219   m_bdpcm = 0;
01220 
01221   const bool   needsSqrt2Scale = TU::needsSqrt2Scale( tu, compID );  // should always be false - transform-skipped blocks don't require sqrt(2) compensation.
01222   const bool   isTransformSkip = (tu.mtsIdx[compID] == MTS_SKIP);
01223   const int    qBits = QUANT_SHIFT + qp.per(isTransformSkip) + (isTransformSkip ? 0 : transformShift) + (needsSqrt2Scale ? -1 : 0);  // Right shift of non-RDOQ quantizer;  level = (coeff*uiQ + offset)>>q_bits
01224   const int    quantisationCoefficient = g_quantScales[needsSqrt2Scale?1:0][qp.rem(isTransformSkip)];
01225   const double errorScale              = xGetErrScaleCoeff( TU::needsSqrt2Scale(tu, compID), width, height, qp.rem(isTransformSkip), maxLog2TrDynamicRange, channelBitDepth, isTransformSkip);
01226 
01227   const TCoeff entropyCodingMaximum = ( 1 << maxLog2TrDynamicRange ) - 1;
01228 
01229   uint32_t coeffLevels[3];
01230   double   coeffLevelError[4];
01231 
01232   CoeffCodingContext cctx( tu, compID, tu.cs->slice->getSignDataHidingEnabledFlag() );
01233   const int sbSizeM1    = ( 1 << cctx.log2CGSize() ) - 1;
01234   double    baseCost    = 0;
01235   uint32_t  goRiceParam = 0;
01236 
01237   double *costSigSubBlock = m_pdCostCoeffGroupSig;
01238   memset( costSigSubBlock, 0, ( maxNumCoeff >> cctx.log2CGSize() ) * sizeof( double ) );
01239 
01240   const int sbNum = width * height >> cctx.log2CGSize();
01241   int scanPos;
01242   coeffGroupRDStats rdStats;
01243 
01244   bool anySigCG = false;
01245 
01246   int maxCtxBins = (cctx.maxNumCoeff() * 7) >> 2;
01247   cctx.setNumCtxBins(maxCtxBins);
01248 
01249   for( int sbId = 0; sbId < sbNum; sbId++ )
01250   {
01251     cctx.initSubblock( sbId );
01252 
01253     int noCoeffCoded = 0;
01254     baseCost = 0.0;
01255     memset( &rdStats, 0, sizeof (coeffGroupRDStats));
01256 
01257     rdStats.iNumSbbCtxBins = 0;
01258 
01259     for( int scanPosInSB = 0; scanPosInSB <= sbSizeM1; scanPosInSB++ )
01260     {
01261       int lastPosCoded = sbSizeM1;
01262       scanPos = cctx.minSubPos() + scanPosInSB;
01263       //===== quantization =====
01264       uint32_t blkPos = cctx.blockPos( scanPos );
01265 
01266       // set coeff
01267       const int64_t          tmpLevel    = int64_t( abs( srcCoeff[blkPos] ) ) * quantisationCoefficient;
01268       const Intermediate_Int levelDouble = (Intermediate_Int)std::min<int64_t>( tmpLevel, std::numeric_limits<Intermediate_Int>::max() - ( Intermediate_Int( 1 ) << ( qBits - 1 ) ) );
01269 
01270       uint32_t roundAbsLevel = std::min<uint32_t>(uint32_t(entropyCodingMaximum), uint32_t((levelDouble + (Intermediate_Int(1) << (qBits - 1))) >> qBits));
01271       uint32_t minAbsLevel = (roundAbsLevel > 1 ? roundAbsLevel - 1 : 1);
01272 
01273       uint32_t downAbsLevel = std::min<uint32_t>(uint32_t(entropyCodingMaximum), uint32_t(levelDouble >> qBits));
01274       uint32_t upAbsLevel = std::min<uint32_t>(uint32_t(entropyCodingMaximum), downAbsLevel + 1);
01275 
01276       m_testedLevels = 0;
01277       coeffLevels[m_testedLevels++] = roundAbsLevel;
01278 
01279       if (minAbsLevel != roundAbsLevel)
01280         coeffLevels[m_testedLevels++] = minAbsLevel;
01281 
01282       int rightPixel, belowPixel, predPixel;
01283 
01284       cctx.neighTS(rightPixel, belowPixel, scanPos, dstCoeff);
01285       predPixel = cctx.deriveModCoeff(rightPixel, belowPixel, upAbsLevel, 0);
01286 
01287       if (upAbsLevel != roundAbsLevel && upAbsLevel != minAbsLevel && predPixel == 1)
01288         coeffLevels[m_testedLevels++] = upAbsLevel;
01289 
01290       double dErr = double(levelDouble);
01291       coeffLevelError[0] = dErr * dErr * errorScale;
01292 
01293       costCoeff0[scanPos] = coeffLevelError[0];
01294       blockUncodedCost   += costCoeff0[ scanPos ];
01295       dstCoeff[blkPos]    = coeffLevels[0];
01296 
01297       //===== coefficient level estimation =====
01298             unsigned    ctxIdSig = cctx.sigCtxIdAbsTS( scanPos, dstCoeff );
01299             uint32_t    cLevel;
01300       const BinFracBits fracBitsPar = fracBits.getFracBitsArray( cctx.parityCtxIdAbsTS() );
01301 
01302       goRiceParam = cctx.templateAbsSumTS( scanPos, dstCoeff );
01303       unsigned ctxIdSign = cctx.signCtxIdAbsTS(scanPos, dstCoeff, 0);
01304       const BinFracBits fracBitsSign = fracBits.getFracBitsArray(ctxIdSign);
01305       const uint8_t     sign         = srcCoeff[ blkPos ] < 0 ? 1 : 0;
01306 
01307       DTRACE_COND( ( coeffLevels[0] != 0 ), g_trace_ctx, D_RDOQ_MORE, " uiCtxSig=%d", ctxIdSig );
01308 
01309       unsigned gt1CtxId = cctx.lrg1CtxIdAbsTS(scanPos, dstCoeff, 0);
01310       const BinFracBits fracBitsGr1 = fracBits.getFracBitsArray(gt1CtxId);
01311 
01312       const BinFracBits fracBitsSig = fracBits.getFracBitsArray( ctxIdSig );
01313       bool lastCoeff = false; //
01314       if (scanPosInSB == lastPosCoded && noCoeffCoded == 0)
01315       {
01316         lastCoeff = true;
01317       }
01318       int numUsedCtxBins = 0;
01319       cLevel = xGetCodedLevelTSPred(costCoeff[scanPos], costCoeff0[scanPos], costSig[scanPos], levelDouble, qBits, errorScale, coeffLevels, coeffLevelError,
01320                                     &fracBitsSig, fracBitsPar, cctx, fracBits, fracBitsSign, fracBitsGr1, sign, rightPixel, belowPixel, goRiceParam, lastCoeff, extendedPrecision, maxLog2TrDynamicRange, numUsedCtxBins);
01321 
01322       cctx.decimateNumCtxBins(numUsedCtxBins);
01323       rdStats.iNumSbbCtxBins += numUsedCtxBins;
01324 
01325 
01326       if (cLevel > 0)
01327       {
01328         noCoeffCoded++;
01329       }
01330 
01331       TCoeff level = cLevel;
01332       dstCoeff[blkPos] = (level != 0 && srcCoeff[blkPos] < 0) ? -level : level;
01333       baseCost           += costCoeff[ scanPos ];
01334       rdStats.d64SigCost += costSig[ scanPos ];
01335 
01336       if( dstCoeff[ blkPos ] )
01337       {
01338         cctx.setSigGroup();
01339         rdStats.d64CodedLevelandDist += costCoeff [ scanPos ] - costSig[ scanPos ];
01340         rdStats.d64UncodedDist       += costCoeff0[ scanPos ];
01341       }
01342     } //end for (iScanPosinCG)
01343 
01344     if( !cctx.isSigGroup() )
01345     {
01346       const BinFracBits fracBitsSigGroup = fracBits.getFracBitsArray( cctx.sigGroupCtxId( true ) );
01347       baseCost += xGetRateSigCoeffGroup( fracBitsSigGroup, 0 ) - rdStats.d64SigCost;
01348       costSigSubBlock[cctx.subSetId()] = xGetRateSigCoeffGroup( fracBitsSigGroup, 0 );
01349       cctx.increaseNumCtxBins(rdStats.iNumSbbCtxBins); // skip sub-block
01350     }
01351     else if( sbId != sbNum - 1 || anySigCG )
01352     {
01353       // rd-cost if SigCoeffGroupFlag = 0, initialization
01354       double costZeroSB = baseCost;
01355 
01356       const BinFracBits fracBitsSigGroup = fracBits.getFracBitsArray( cctx.sigGroupCtxId( true ) );
01357 
01358       baseCost   += xGetRateSigCoeffGroup( fracBitsSigGroup, 1 );
01359       costZeroSB += xGetRateSigCoeffGroup( fracBitsSigGroup, 0 );
01360       costSigSubBlock[ cctx.subSetId() ] = xGetRateSigCoeffGroup( fracBitsSigGroup, 1 );
01361 
01362       costZeroSB += rdStats.d64UncodedDist;         // distortion for resetting non-zero levels to zero levels
01363       costZeroSB -= rdStats.d64CodedLevelandDist;   // distortion and level cost for keeping all non-zero levels
01364       costZeroSB -= rdStats.d64SigCost;             // sig cost for all coeffs, including zero levels and non-zerl levels
01365 
01366       if( costZeroSB < baseCost )
01367       {
01368         cctx.resetSigGroup();
01369         baseCost = costZeroSB;
01370         costSigSubBlock[ cctx.subSetId() ] = xGetRateSigCoeffGroup( fracBitsSigGroup, 0 );
01371         cctx.increaseNumCtxBins(rdStats.iNumSbbCtxBins); // skip sub-block
01372         for( int scanPosInSB = 0; scanPosInSB <= sbSizeM1; scanPosInSB++ )
01373         {
01374           scanPos = cctx.minSubPos() + scanPosInSB;
01375           uint32_t blkPos = cctx.blockPos( scanPos );
01376 
01377           if( dstCoeff[ blkPos ] )
01378           {
01379             dstCoeff[ blkPos ] = 0;
01380             costCoeff[ scanPos ] = costCoeff0[ scanPos ];
01381             costSig[ scanPos] = 0;
01382           }
01383         }
01384       }
01385       else
01386       {
01387         anySigCG = true;
01388       }
01389     }
01390   }
01391 
01392   //===== estimate last position =====
01393   for( int scanPos = 0; scanPos < maxNumCoeff; scanPos++ )
01394   {
01395     int blkPos = cctx.blockPos( scanPos );
01396     TCoeff level = dstCoeff[ blkPos ];
01397     absSum += abs(level);
01398   }
01399 }
