01401 void QuantRDOQ::forwardBDPCM(TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &coeffs, TCoeff &absSum,
01402                              const QpParam &qp, const Ctx &ctx)
01403 {
01404   const FracBitsAccess& fracBits = ctx.getFracBitsAcess();
01405 
01406   const SPS &sps = *tu.cs->sps;
01407   const CompArea &rect = tu.blocks[compID];
01408   const uint32_t width = rect.width;
01409   const uint32_t height = rect.height;
01410   const ChannelType chType = toChannelType(compID);
01411   const int channelBitDepth = sps.getBitDepth(chType);
01412 
01413   const bool extendedPrecision = sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag();
01414   const int  maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange(chType);
01415   const int  dirMode = isLuma(compID) ? tu.cu->bdpcmMode : tu.cu->bdpcmModeChroma;
01416   int transformShift = getTransformShift(channelBitDepth, rect.size(), maxLog2TrDynamicRange);
01417 
01418   if (extendedPrecision)
01419   {
01420     transformShift = std::max<int>(0, transformShift);
01421   }
01422 
01423   double   blockUncodedCost = 0;
01424   const uint32_t maxNumCoeff = rect.area();
01425 
01426   CHECK(compID >= MAX_NUM_TBLOCKS, "Invalid component ID");
01427 
01428   int scalingListType = getScalingListType(tu.cu->predMode, compID);
01429   CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
01430 
01431   const TCoeff *srcCoeff = coeffs.buf;
01432   TCoeff *dstCoeff = tu.getCoeffs(compID).buf;
01433 
01434   double *costCoeff = m_pdCostCoeff;
01435   double *costSig = m_pdCostSig;
01436   double *costCoeff0 = m_pdCostCoeff0;
01437 
01438   memset(m_pdCostCoeff, 0, sizeof(double) *  maxNumCoeff);
01439   memset(m_pdCostSig, 0, sizeof(double) *  maxNumCoeff);
01440   memset(m_fullCoeff, 0, sizeof(TCoeff) * maxNumCoeff);
01441 
01442   m_bdpcm = dirMode;
01443 
01444   const bool   needsSqrt2Scale = TU::needsSqrt2Scale(tu, compID);  // should always be false - transform-skipped blocks don't require sqrt(2) compensation.
01445   const bool   isTransformSkip = (tu.mtsIdx[compID] == MTS_SKIP);
01446   const int    qBits = QUANT_SHIFT + qp.per(isTransformSkip) + (isTransformSkip? 0 : transformShift) + ( needsSqrt2Scale ? -1 : 0);  // Right shift of non-RDOQ quantizer;  level = (coeff*uiQ + offset)>>q_bits
01447   const int    quantisationCoefficient = g_quantScales[needsSqrt2Scale ? 1 : 0][qp.rem(isTransformSkip)];
01448   const double errorScale = xGetErrScaleCoeff(TU::needsSqrt2Scale(tu, compID), width, height, qp.rem(isTransformSkip), maxLog2TrDynamicRange, channelBitDepth, isTransformSkip);
01449   TrQuantParams trQuantParams;
01450   trQuantParams.rightShift = (IQUANT_SHIFT - ((isTransformSkip ? 0 : transformShift) + qp.per(isTransformSkip)));
01451   trQuantParams.qScale = g_invQuantScales[needsSqrt2Scale ? 1 : 0][qp.rem(isTransformSkip)];
01452 
01453   const TCoeff entropyCodingMaximum = (1 << maxLog2TrDynamicRange) - 1;
01454 
01455   uint32_t coeffLevels[3];
01456   double   coeffLevelError[4];
01457 
01458   CoeffCodingContext cctx(tu, compID, tu.cs->slice->getSignDataHidingEnabledFlag());
01459   const int sbSizeM1 = (1 << cctx.log2CGSize()) - 1;
01460   double    baseCost = 0;
01461   uint32_t  goRiceParam = 0;
01462 
01463   double *costSigSubBlock = m_pdCostCoeffGroupSig;
01464   memset(costSigSubBlock, 0, (maxNumCoeff >> cctx.log2CGSize()) * sizeof(double));
01465 
01466   const int sbNum = width * height >> cctx.log2CGSize();
01467   int scanPos;
01468   coeffGroupRDStats rdStats;
01469 
01470   bool anySigCG = false;
01471 
01472   int maxCtxBins = (cctx.maxNumCoeff() * 7) >> 2;
01473   cctx.setNumCtxBins(maxCtxBins);
01474 
01475   for (int sbId = 0; sbId < sbNum; sbId++)
01476   {
01477     cctx.initSubblock(sbId);
01478 
01479     int noCoeffCoded = 0;
01480     baseCost = 0.0;
01481     memset(&rdStats, 0, sizeof(coeffGroupRDStats));
01482     rdStats.iNumSbbCtxBins = 0;
01483 
01484     for (int scanPosInSB = 0; scanPosInSB <= sbSizeM1; scanPosInSB++)
01485     {
01486       int lastPosCoded = sbSizeM1;
01487       scanPos = cctx.minSubPos() + scanPosInSB;
01488       //===== quantization =====
01489       uint32_t blkPos = cctx.blockPos(scanPos);
01490 
01491       const int posX = cctx.posX(scanPos);
01492       const int posY = cctx.posY(scanPos);
01493       const int posS = (1 == dirMode) ? posX : posY;
01494       const int posNb = (1 == dirMode) ? (posX - 1) + posY * coeffs.stride : posX + (posY - 1) * coeffs.stride;
01495       TCoeff predCoeff = (0 != posS) ? m_fullCoeff[posNb] : 0;
01496 
01497       // set coeff
01498       const int64_t          tmpLevel = int64_t(abs(srcCoeff[blkPos] - predCoeff)) * quantisationCoefficient;
01499       const Intermediate_Int levelDouble = (Intermediate_Int)std::min<int64_t>(tmpLevel, std::numeric_limits<Intermediate_Int>::max() - (Intermediate_Int(1) << (qBits - 1)));
01500       uint32_t roundAbsLevel = std::min<uint32_t>(uint32_t(entropyCodingMaximum), uint32_t((levelDouble + (Intermediate_Int(1) << (qBits - 1))) >> qBits));
01501       uint32_t minAbsLevel = (roundAbsLevel > 1 ? roundAbsLevel - 1 : 1);
01502 
01503       m_testedLevels = 0;
01504       coeffLevels[m_testedLevels++] = roundAbsLevel;
01505 
01506       if (minAbsLevel != roundAbsLevel)
01507         coeffLevels[m_testedLevels++] = minAbsLevel;
01508 
01509       double dErr = double(levelDouble);
01510       coeffLevelError[0]  = dErr * dErr * errorScale;
01511 
01512       costCoeff0[scanPos] = coeffLevelError[0];
01513       blockUncodedCost   += costCoeff0[scanPos];
01514       dstCoeff[blkPos]    = coeffLevels[0];
01515 
01516       //===== coefficient level estimation =====
01517       unsigned    ctxIdSig = cctx.sigCtxIdAbsTS(scanPos, dstCoeff);
01518       uint32_t    cLevel;
01519       const BinFracBits fracBitsPar = fracBits.getFracBitsArray(cctx.parityCtxIdAbsTS());
01520 
01521       goRiceParam = cctx.templateAbsSumTS(scanPos, dstCoeff);
01522       unsigned ctxIdSign = cctx.signCtxIdAbsTS(scanPos, dstCoeff, dirMode);
01523       const BinFracBits fracBitsSign = fracBits.getFracBitsArray(ctxIdSign);
01524       const uint8_t     sign = srcCoeff[blkPos] - predCoeff < 0 ? 1 : 0;
01525       unsigned gt1CtxId = cctx.lrg1CtxIdAbsTS(scanPos, dstCoeff, dirMode);
01526       const BinFracBits fracBitsGr1 = fracBits.getFracBitsArray(gt1CtxId);
01527 
01528       DTRACE_COND((dstCoeff[blkPos] != 0), g_trace_ctx, D_RDOQ_MORE, " uiCtxSig=%d", ctxIdSig);
01529 
01530       const BinFracBits fracBitsSig = fracBits.getFracBitsArray(ctxIdSig);
01531       bool lastCoeff = false; //
01532       if (scanPosInSB == lastPosCoded && noCoeffCoded == 0)
01533       {
01534         lastCoeff = true;
01535       }
01536       int rightPixel, belowPixel;
01537       cctx.neighTS(rightPixel, belowPixel, scanPos, dstCoeff);
01538       int numUsedCtxBins = 0;
01539       cLevel = xGetCodedLevelTSPred(costCoeff[scanPos], costCoeff0[scanPos], costSig[scanPos], levelDouble, qBits, errorScale, coeffLevels, coeffLevelError,
01540         &fracBitsSig, fracBitsPar, cctx, fracBits, fracBitsSign, fracBitsGr1, sign, rightPixel, belowPixel, goRiceParam, lastCoeff, extendedPrecision, maxLog2TrDynamicRange, numUsedCtxBins);
01541       cctx.decimateNumCtxBins(numUsedCtxBins);
01542       rdStats.iNumSbbCtxBins += numUsedCtxBins;
01543       if (cLevel > 0)
01544       {
01545         noCoeffCoded++;
01546       }
01547       dstCoeff[blkPos] = cLevel;
01548 
01549       if (sign)
01550       {
01551         dstCoeff[blkPos] = -dstCoeff[blkPos];
01552       }
01553       xDequantSample( m_fullCoeff[blkPos], dstCoeff[blkPos], trQuantParams );
01554       m_fullCoeff[blkPos] += predCoeff;
01555 
01556       baseCost += costCoeff[scanPos];
01557       rdStats.d64SigCost += costSig[scanPos];
01558 
01559       if (dstCoeff[blkPos])
01560       {
01561         cctx.setSigGroup();
01562         rdStats.d64CodedLevelandDist += costCoeff[scanPos] - costSig[scanPos];
01563         rdStats.d64UncodedDist += costCoeff0[scanPos];
01564       }
01565     } //end for (iScanPosinCG)
01566 
01567     if (!cctx.isSigGroup())
01568     {
01569       const BinFracBits fracBitsSigGroup = fracBits.getFracBitsArray(cctx.sigGroupCtxId(true));
01570       baseCost += xGetRateSigCoeffGroup(fracBitsSigGroup, 0) - rdStats.d64SigCost;
01571       costSigSubBlock[cctx.subSetId()] = xGetRateSigCoeffGroup(fracBitsSigGroup, 0);
01572       cctx.increaseNumCtxBins(rdStats.iNumSbbCtxBins); // skip sub-block
01573     }
01574     else if (sbId != sbNum - 1 || anySigCG)
01575     {
01576       // rd-cost if SigCoeffGroupFlag = 0, initialization
01577       double costZeroSB = baseCost;
01578 
01579       const BinFracBits fracBitsSigGroup = fracBits.getFracBitsArray(cctx.sigGroupCtxId(true));
01580 
01581       baseCost += xGetRateSigCoeffGroup(fracBitsSigGroup, 1);
01582       costZeroSB += xGetRateSigCoeffGroup(fracBitsSigGroup, 0);
01583       costSigSubBlock[cctx.subSetId()] = xGetRateSigCoeffGroup(fracBitsSigGroup, 1);
01584 
01585       costZeroSB += rdStats.d64UncodedDist;         // distortion for resetting non-zero levels to zero levels
01586       costZeroSB -= rdStats.d64CodedLevelandDist;   // distortion and level cost for keeping all non-zero levels
01587       costZeroSB -= rdStats.d64SigCost;             // sig cost for all coeffs, including zero levels and non-zerl levels
01588 
01589       if (costZeroSB < baseCost)
01590       {
01591         cctx.resetSigGroup();
01592         baseCost = costZeroSB;
01593         costSigSubBlock[cctx.subSetId()] = xGetRateSigCoeffGroup(fracBitsSigGroup, 0);
01594         cctx.increaseNumCtxBins(rdStats.iNumSbbCtxBins); // skip sub-block
01595 
01596         for (int scanPosInSB = 0; scanPosInSB <= sbSizeM1; scanPosInSB++)
01597         {
01598           scanPos = cctx.minSubPos() + scanPosInSB;
01599           uint32_t blkPos = cctx.blockPos(scanPos);
01600 
01601           const int posX = cctx.posX(scanPos);
01602           const int posY = cctx.posY(scanPos);
01603           const int posS = (1 == dirMode) ? posX : posY;
01604           const int posNb = (1 == dirMode) ? (posX - 1) + posY * coeffs.stride : posX + (posY - 1) * coeffs.stride;
01605           m_fullCoeff[scanPos] = (0 != posS) ? m_fullCoeff[posNb] : 0;
01606 
01607           if (dstCoeff[blkPos])
01608           {
01609             dstCoeff[blkPos] = 0;
01610             costCoeff[scanPos] = costCoeff0[scanPos];
01611             costSig[scanPos] = 0;
01612           }
01613         }
01614       }
01615       else
01616       {
01617         anySigCG = true;
01618       }
01619     }
01620   }
01621 
01622   //===== estimate last position =====
01623   for (int scanPos = 0; scanPos < maxNumCoeff; scanPos++)
01624   {
01625     int blkPos = cctx.blockPos(scanPos);
01626     TCoeff level = dstCoeff[blkPos];
01627     absSum += abs(level);
01628   }
01629 }
01630 
01631 void QuantRDOQ::xDequantSample(TCoeff& pRes, TCoeff& coeff, const TrQuantParams& trQuantParams)
01632 {
01633   // xDequant
01634   if (trQuantParams.rightShift > 0)
01635   {
01636     const Intermediate_Int qAdd = Intermediate_Int(1) << (trQuantParams.rightShift - 1);
01637     pRes = TCoeff((Intermediate_Int(coeff) * trQuantParams.qScale + qAdd) >> trQuantParams.rightShift);
01638   }
01639   else
01640   {
01641     pRes = TCoeff((Intermediate_Int(coeff) * trQuantParams.qScale) << -trQuantParams.rightShift);
01642   }
01643 }
01644 
01645 inline uint32_t QuantRDOQ::xGetCodedLevelTSPred(double&            rd64CodedCost,
01646   double&            rd64CodedCost0,
01647   double&            rd64CodedCostSig,
01648   Intermediate_Int    levelDouble,
01649   int                 qBits,
01650   double              errorScale,
01651   uint32_t coeffLevels[],
01652   double coeffLevelError[],
01653   const BinFracBits* fracBitsSig,
01654   const BinFracBits& fracBitsPar,
01655   CoeffCodingContext& cctx,
01656   const FracBitsAccess& fracBitsAccess,
01657   const BinFracBits& fracBitsSign,
01658   const BinFracBits& fracBitsGt1,
01659   const uint8_t      sign,
01660   int                rightPixel,
01661   int                belowPixel,
01662   uint16_t           ricePar,
01663   bool               isLast,
01664   bool               useLimitedPrefixLength,
01665   const int          maxLog2TrDynamicRange
01666   , int&               numUsedCtxBins
01667 ) const
01668 {
01669   double currCostSig = 0;
01670   uint32_t   bestAbsLevel = 0;
01671   numUsedCtxBins = 0;
01672   int numBestCtxBin = 0;
01673   if (!isLast && coeffLevels[0] < 3)
01674   {
01675     if (cctx.numCtxBins() >= 4)
01676       rd64CodedCostSig = xGetRateSigCoef(*fracBitsSig, 0);
01677     else
01678       rd64CodedCostSig = xGetICost(1 << SCALE_BITS);
01679     rd64CodedCost = rd64CodedCost0 + rd64CodedCostSig;
01680     if (cctx.numCtxBins() >= 4)
01681       numUsedCtxBins++;
01682     if (coeffLevels[0] == 0)
01683     {
01684       return bestAbsLevel;
01685     }
01686   }
01687   else
01688   {
01689     rd64CodedCost = MAX_DOUBLE;
01690   }
01691 
01692   if (!isLast)
01693   {
01694     if (cctx.numCtxBins() >= 4)
01695       currCostSig = xGetRateSigCoef(*fracBitsSig, 1);
01696     else
01697       currCostSig = xGetICost(1 << SCALE_BITS);
01698     if (coeffLevels[0] >= 3 && cctx.numCtxBins() >= 4)
01699       numUsedCtxBins++;
01700   }
01701 
01702   for (int errorInd = 1; errorInd <= m_testedLevels; errorInd++)
01703   {
01704     int absLevel = coeffLevels[errorInd - 1];
01705     double dErr = 0.0;
01706     dErr = double(levelDouble - (Intermediate_Int(absLevel) << qBits));
01707     coeffLevelError[errorInd] = dErr * dErr * errorScale;
01708     int modAbsLevel = absLevel;
01709     if (cctx.numCtxBins() >= 4)
01710     {
01711       modAbsLevel = cctx.deriveModCoeff(rightPixel, belowPixel, absLevel, m_bdpcm);
01712     }
01713     int numCtxBins = 0;
01714     double dCurrCost = coeffLevelError[errorInd] + xGetICost(xGetICRateTS(modAbsLevel, fracBitsPar, cctx, fracBitsAccess, fracBitsSign, fracBitsGt1, numCtxBins, sign, ricePar, useLimitedPrefixLength, maxLog2TrDynamicRange));
01715 
01716     if (cctx.numCtxBins() >= 4)
01717       dCurrCost += currCostSig; // if cctx.numCtxBins < 4, xGetICRateTS return rate including sign cost. dont need to add any more
01718 
01719     if (dCurrCost < rd64CodedCost)
01720     {
01721       bestAbsLevel = absLevel;
01722       rd64CodedCost = dCurrCost;
01723       rd64CodedCostSig = currCostSig;
01724       numBestCtxBin = numCtxBins;
01725     }
01726   }
01727   numUsedCtxBins += numBestCtxBin;
01728   return bestAbsLevel;
01729 }
01730 
01731 inline int QuantRDOQ::xGetICRateTS( const uint32_t            absLevel,
01732                                     const BinFracBits&        fracBitsPar,
01733                                     const CoeffCodingContext& cctx,
01734                                     const FracBitsAccess&     fracBitsAccess,
01735                                     const BinFracBits&        fracBitsSign,
01736                                     const BinFracBits&        fracBitsGt1,
01737                                     int&                      numCtxBins,
01738                                     const uint8_t             sign,
01739                                     const uint16_t            ricePar,
01740                                     const bool                useLimitedPrefixLength,
01741                                     const int                 maxLog2TrDynamicRange  ) const
01742 {
01743 
01744 
01745   if (cctx.numCtxBins() < 4) // Full by-pass coding
01746   {
01747     int rate = absLevel ? (1 << SCALE_BITS) : 0; // 1 bit to signal sign of non-zero
01748 
01749     uint32_t symbol = absLevel;
01750 
01751     uint32_t length;
01752     const int threshold = COEF_REMAIN_BIN_REDUCTION;
01753     if (symbol < (threshold << ricePar))
01754     {
01755       length = symbol >> ricePar;
01756       rate += (length + 1 + ricePar) << SCALE_BITS;
01757     }
01758     else if (useLimitedPrefixLength)
01759     {
01760       const uint32_t maximumPrefixLength = (32 - (COEF_REMAIN_BIN_REDUCTION + maxLog2TrDynamicRange));
01761 
01762       uint32_t prefixLength = 0;
01763       uint32_t suffix = (symbol >> ricePar) - COEF_REMAIN_BIN_REDUCTION;
01764 
01765       while ((prefixLength < maximumPrefixLength) && (suffix > ((2 << prefixLength) - 2)))
01766       {
01767         prefixLength++;
01768       }
01769 
01770       const uint32_t suffixLength = (prefixLength == maximumPrefixLength) ? (maxLog2TrDynamicRange - ricePar) : (prefixLength + 1/*separator*/);
01771 
01772       rate += (COEF_REMAIN_BIN_REDUCTION + prefixLength + suffixLength + ricePar) << SCALE_BITS;
01773     }
01774     else
01775     {
01776       length = ricePar;
01777       symbol = symbol - (threshold << ricePar);
01778       while (symbol >= (1 << length))
01779       {
01780         symbol -= (1 << (length++));
01781       }
01782       rate += (threshold + length + 1 - ricePar + length) << SCALE_BITS;
01783     }
01784 
01785     return rate;
01786   }
01787 
01788   else if (cctx.numCtxBins() >= 4 && cctx.numCtxBins() < 8) // First pass context coding and all by-pass coding ( Sign flag is not counted here)
01789   {
01790     int rate = fracBitsSign.intBits[sign]; // sign bits
01791     if (absLevel)
01792       numCtxBins++;
01793 
01794     if (absLevel > 1)
01795     {
01796       rate += fracBitsGt1.intBits[1];
01797       rate += fracBitsPar.intBits[(absLevel - 2) & 1];
01798 
01799       numCtxBins += 2;
01800 
01801       int cutoffVal = 2;
01802 
01803       if (absLevel >= cutoffVal)
01804       {
01805         uint32_t symbol = (absLevel - cutoffVal) >> 1;
01806         uint32_t length;
01807         const int threshold = COEF_REMAIN_BIN_REDUCTION;
01808         if (symbol < (threshold << ricePar))
01809         {
01810           length = symbol >> ricePar;
01811           rate += (length + 1 + ricePar) << SCALE_BITS;
01812         }
01813         else if (useLimitedPrefixLength)
01814         {
01815           const uint32_t maximumPrefixLength = (32 - (COEF_REMAIN_BIN_REDUCTION + maxLog2TrDynamicRange));
01816 
01817           uint32_t prefixLength = 0;
01818           uint32_t suffix = (symbol >> ricePar) - COEF_REMAIN_BIN_REDUCTION;
01819 
01820           while ((prefixLength < maximumPrefixLength) && (suffix > ((2 << prefixLength) - 2)))
01821           {
01822             prefixLength++;
01823           }
01824 
01825           const uint32_t suffixLength = (prefixLength == maximumPrefixLength) ? (maxLog2TrDynamicRange - ricePar) : (prefixLength + 1/*separator*/);
01826 
01827           rate += (COEF_REMAIN_BIN_REDUCTION + prefixLength + suffixLength + ricePar) << SCALE_BITS;
01828         }
01829         else
01830         {
01831           length = ricePar;
01832           symbol = symbol - (threshold << ricePar);
01833           while (symbol >= (1 << length))
01834           {
01835             symbol -= (1 << (length++));
01836           }
01837           rate += (threshold + length + 1 - ricePar + length) << SCALE_BITS;
01838         }
01839       }
01840     }
01841     else if (absLevel == 1)
01842     {
01843       rate += fracBitsGt1.intBits[0];
01844       numCtxBins++;
01845     }
01846     else
01847     {
01848       rate = 0;
01849     }
01850     return rate;
01851 
01852   }
01853 
01854 
01855 
01856   int rate = fracBitsSign.intBits[sign];
01857 
01858   if (absLevel)
01859     numCtxBins++;
01860 
01861   if( absLevel > 1 )
01862   {
01863     rate += fracBitsGt1.intBits[1];
01864     rate += fracBitsPar.intBits[( absLevel - 2 ) & 1];
01865     numCtxBins += 2;
01866 
01867           int cutoffVal = 2;
01868     const int numGtBins = 4;
01869     for( int i = 0; i < numGtBins; i++ )
01870     {
01871       if( absLevel >= cutoffVal )
01872       {
01873         const uint16_t ctxGtX = cctx.greaterXCtxIdAbsTS( cutoffVal>>1 );
01874         const BinFracBits &fracBitsGtX = fracBitsAccess.getFracBitsArray( ctxGtX );
01875         unsigned gtX = ( absLevel >= ( cutoffVal + 2 ) );
01876         rate += fracBitsGtX.intBits[gtX];
01877         numCtxBins++;
01878       }
01879       cutoffVal += 2;
01880     }
01881 
01882     if( absLevel >= cutoffVal )
01883     {
01884       uint32_t symbol = ( absLevel - cutoffVal ) >> 1;
01885       uint32_t length;
01886       const int threshold = COEF_REMAIN_BIN_REDUCTION;
01887       if( symbol < ( threshold << ricePar ) )
01888       {
01889         length = symbol >> ricePar;
01890         rate  += ( length + 1 + ricePar ) << SCALE_BITS;
01891       }
01892       else if( useLimitedPrefixLength )
01893       {
01894         const uint32_t maximumPrefixLength = ( 32 - ( COEF_REMAIN_BIN_REDUCTION + maxLog2TrDynamicRange ) );
01895 
01896         uint32_t prefixLength = 0;
01897         uint32_t suffix = ( symbol >> ricePar ) - COEF_REMAIN_BIN_REDUCTION;
01898 
01899         while( ( prefixLength < maximumPrefixLength ) && ( suffix > ( ( 2 << prefixLength ) - 2 ) ) )
01900         {
01901           prefixLength++;
01902         }
01903 
01904         const uint32_t suffixLength = ( prefixLength == maximumPrefixLength ) ? ( maxLog2TrDynamicRange - ricePar ) : ( prefixLength + 1/*separator*/ );
01905 
01906         rate += ( COEF_REMAIN_BIN_REDUCTION + prefixLength + suffixLength + ricePar ) << SCALE_BITS;
01907       }
01908       else
01909       {
01910         length = ricePar;
01911         symbol = symbol - ( threshold << ricePar );
01912         while( symbol >= ( 1 << length ) )
01913         {
01914           symbol -= ( 1 << ( length++ ) );
01915         }
01916         rate += ( threshold + length + 1 - ricePar + length ) << SCALE_BITS;
01917       }
01918     }
01919   }
01920   else if( absLevel == 1 )
01921   {
01922     rate += fracBitsGt1.intBits[0];
01923     numCtxBins++;
01924   }
01925   else
01926   {
01927     rate = 0;
01928   }
01929   return rate;
01930 }
